"use server";

import { createServerClient } from '@supabase/ssr';
import { cookies } from 'next/headers';
import { revalidatePath } from 'next/cache';

/**
 * Fungsi untuk menyimpan data surveilans secara massal
 */
export async function saveSurveilansMassal(dataRows: any[]) {
  const cookieStore = await cookies();
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() { return cookieStore.getAll() },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options)
            )
          } catch {}
        },
      },
    }
  );

  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error("Unauthorized");

  // Ambil ruangan_id dari profil user yang login
  const { data: profile } = await supabase
    .from('profiles')
    .select('ruangan_id')
    .eq('id', user.id)
    .single();

  // Tambahkan user_id dan ruangan_id ke setiap baris data
  const finalData = dataRows.map(row => ({
    ...row,
    user_id: user.id,
    ruangan_id: profile?.ruangan_id
  }));

  const { error } = await supabase.from('surveilans_harian').insert(finalData);
  if (error) throw error;

  // Revalidasi agar data di dashboard langsung berubah
  revalidatePath('/dashboard/perawat');
  return { success: true };
}

/**
 * Fungsi: Menghitung jumlah pasien dan indikator khusus hari ini
 * Diperbarui dengan logika Zona Waktu Asia/Jakarta agar sinkron dengan database
 */
export async function getStatsHariIni() {
  const cookieStore = await cookies();
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    { cookies: { getAll() { return cookieStore.getAll() } } }
  );

  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return { totalPasien: 0, totalTindakan: 0, potensiHais: 0 };

  // Pastikan tanggal sesuai zona waktu Indonesia (WIB) agar tidak meleset ke hari kemarin/besok
  const today = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Jakarta',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(new Date());

  const { data, error } = await supabase
    .from('surveilans_harian')
    .select('*')
    .eq('user_id', user.id)
    .eq('tanggal', today);

  if (error || !data) {
    console.error("Fetch stats error:", error);
    return { totalPasien: 0, totalTindakan: 0, potensiHais: 0 };
  }

  // 1. Total Pasien: Jumlah baris data unik hari ini
  const totalPasien = data.length;

  // 2. Total Tindakan: Akumulasi pemakaian alat (UC + CVL + IVL + ETT)
  const totalTindakan = data.reduce((acc, curr) => 
    acc + (Number(curr.uc) || 0) + (Number(curr.cvl) || 0) + (Number(curr.ivl) || 0) + (Number(curr.ett) || 0), 0
  );

  // 3. Potensi HAIs: Akumulasi temuan infeksi (VAP + IDO + ISK + IAD)
  const potensiHais = data.reduce((acc, curr) => 
    acc + (Number(curr.vap) || 0) + (Number(curr.ido) || 0) + (Number(curr.isk) || 0) + (Number(curr.iad) || 0), 0
  );

  return { totalPasien, totalTindakan, potensiHais };
}